 for vcf_file in "$VCF_DIR"/*_chr.vcf.gz; do     echo "=== Procesando archivo: $vcf_file ===";          nextflow run workflow/main.nf       --profile singularity       --input "$vcf_file"       --build GRCh38       --out "$OUT_DIR"       --scores best       --regions best       --AF       --greenvaran_config "$BASE_DIR/config/prioritize_smallvars.json"       --greenvaran_dbschema "$BASE_DIR/config/greendb_schema_v2.5.json"       --resource_folder "$BASE_DIR/resources";      if [ $? -eq 0 ]; then         echo "¡Procesamiento exitoso para $vcf_file!";     else         echo "ERROR: Falló el procesamiento de $vcf_file";         exit 1;     fi; done
